            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    if not raw_id:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Resource id must not be empty.",
        )
    if "/" in raw_id or "\\" in raw_id:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Resource id must not contain path separators.",
        )

    resource = store.get(raw_id)
    if resource is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    return _resource_response(start_response, "200 OK", resource)


def application(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))

        if method == "GET" and path == "/health":
            # Kept byte-for-byte compatible with the documented baseline.
            return _json_response(start_response, "200 OK", {"status": "ok"})

        if path == "/resources":
            if method == "GET":
                return _json_response(
                    start_response,
                    "200 OK",
                    {"resources": [r.to_dict() for r in store.list_all()]},
                    trailing_newline=True,
                )
            if method == "POST":
                return _handle_resources_post(environ, start_response)
            return _error(
                start_response,
                "405 Method Not Allowed",
                "method_not_allowed",
                f"Method {method} is not allowed for this path.",
            )

        if path.startswith("/resources/"):
            return _handle_resource_item(
                method, path[len("/resources/"):], start_response
            )

        # Unknown paths and undeclared methods on /health stay as before.
        return _json_response(
            start_response,
            "404 Not Found",
            {"error": "not_found", "message": "The requested resource does not exist."},
        )
    except Exception:  # pragma: no cover - defensive boundary
        # Clients must only ever see agreed statuses, never a stack trace.
        return _error(
            start_response,
            "500 Internal Server Error",
            "internal_error",
            "An unexpected error occurred.",
        )

from __future__ import annotations

import json
import unittest

from provenance_api.app import application


def request(method: str, path: str) -> tuple[str, list[tuple[str, str]], dict[str, object]]:
    captured: dict[str, object] = {}

    def start_response(status: str, headers: list[tuple[str, str]]) -> None:
        captured["status"] = status
        captured["headers"] = headers

    chunks = application(
        {"REQUEST_METHOD": method, "PATH_INFO": path}, start_response
    )
    body = json.loads(b"".join(chunks).decode("utf-8"))
    return str(captured["status"]), list(captured["headers"]), body


class ApplicationTests(unittest.TestCase):
    def test_health(self) -> None:
        status, headers, body = request("GET", "/health")

        self.assertEqual(status, "200 OK")
        self.assertIn(("Content-Type", "application/json; charset=utf-8"), headers)
        self.assertEqual(body, {"status": "ok"})

    def test_unknown_path(self) -> None:
        status, _headers, body = request("GET", "/missing")

        self.assertEqual(status, "404 Not Found")
        self.assertEqual(body["error"], "not_found")


if __name__ == "__main__":
    unittest.main()
